const BalanceDefinitionSchema = z
  .object({
    id: z
      .uuid()
      .exactOptional()
      .openapi({ description: 'Unique identifier for the balance definition.' }),
    name: z.string().exactOptional().openapi({ description: 'Name of the balance definition.' }),
    description: z
      .string()
      .exactOptional()
      .openapi({ description: 'Short description of the balance definition.' }),
    imageRef: z.url().exactOptional().openapi({ description: 'Optional image reference URL.' }),
    meta: z
      .record(z.string(), z.any())
      .exactOptional()
      .openapi({ description: 'Additional metadata for the balance definition.' }),
    unit: z
      .enum([
        'POINTS',
        'EUR',
        'USD',
        'MXN',
        'GBP',
        'INR',
        'CAD',
        'SGD',
        'RON',
        'JPY',
        'MYR',
        'CLP',
        'PEN',
        'MAD',
        'AUD',
        'CHF',
        'BRL',
      ])
      .exactOptional()
      .openapi({ description: 'Unit of balance measurement.' }),
    minAmount: z.number().exactOptional().openapi({ description: 'Minimum allowable balance.' }),
    maxAmount: z.number().exactOptional().openapi({ description: 'Maximum allowable balance.' }),
    maxCreditAmountLimit: z
      .number()
      .exactOptional()
      .openapi({ description: 'Maximum credit allowed per operation.' }),
    maxDebitAmountLimit: z
      .number()
      .exactOptional()
      .openapi({ description: 'Maximum debit allowed per operation.' }),
    balanceOptionAmountOvertakingStrategy: z
      .enum(['strict', 'partial'])
      .exactOptional()
      .openapi({
        description:
          'Partial enables partial credit of balance if maximum balance limit is reached. Strict enables rejection of a transaction if it will breach the max balance limit.',
      }),
    balanceOptionCreditRounding: z
      .enum(['lower', 'upper', 'natural'])
      .exactOptional()
      .openapi({ description: 'Rounding strategy for credit transactions.' }),
    balanceOptionDebitRounding: z
      .enum(['lower', 'upper', 'natural'])
      .exactOptional()
      .openapi({ description: 'Rounding strategy for debit transactions.' }),
    balanceAvailabilityDurationValue: z
      .int()
      .exactOptional()
      .openapi({ description: 'Number of time units before the balance expires.' }),
    balanceAvailabilityDurationUnit: z
      .enum(['day', 'week', 'month', 'year'])
      .exactOptional()
      .openapi({ description: 'Unit of time for the balance availability duration.' }),
    balanceAvailabilityDurationModifier: z
      .enum(['noModification', 'startOfPeriod', 'endOfPeriod'])
      .exactOptional()
      .openapi({
        description:
          'Modifier for balance availability duration. startOfPeriod causes expiry at the start of the period, endOfPeriod at the end. noModification uses the exact duration from the credit date.',
      }),
    balanceExpirationDate: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Fixed expiration date in dd/mm format. The balance expires when this date next appears in the calendar. Only one of balanceExpirationDate or balance availability duration fields can be used.',
      }),
    createdAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'Timestamp of balance definition creation.' }),
    updatedAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'Timestamp of the last update.' }),
    deletedAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'Timestamp of balance definition deletion (nullable).' }),
  })
  .openapi({ required: [] })
  .openapi('BalanceDefinition')

const BalanceLimitSchema = z
