export const deleteCorporateSubAccountIdRoute = createRoute({
  method: 'delete',
  path: '/corporate/subAccount/{id}',
  tags: ['Master account'],
  summary: 'Delete a sub-account',
  description:
    'Permanently deletes a sub-account from the corporate master account. Once deleted, all data associated with the sub-account organization is removed and cannot be recovered, so ensure the sub-account is no longer needed before proceeding.',
  request: {
    params: z.object({
      id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description: 'Id of the sub-account organization to be deleted',
            in: 'path',
            name: 'id',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    204: { description: 'Returned when sub-account is deleted succesfully' },
    400: {
      description: 'bad request',
      content: {
        'application/json': {
          schema: ErrorModelSchema,
          example: { code: 'missing_parameter', message: 'Sub-account 2039dfsddf885 is not valid' },
        },
      },
    },
    404: {
      description: 'sub-account not found',
      content: {
        'application/json': {
          schema: ErrorModelSchema,
          example: { code: 'document_not_found', message: 'Sub-account 2039885 was not found' },
        },
      },
    },
  },
})

