export const getOrganizationActivitiesRoute = createRoute({
  method: 'get',
  path: '/organization/activities',
  tags: ['Account', 'Master account'],
  summary: 'Get user activity logs',
  description:
    'Retrieves user activity logs from your organization for security monitoring and audit compliance.\n\nUse this to:\n- Monitor user login activities and access patterns\n- Track account modifications and configuration changes\n- Generate security audit reports and compliance documentation\n- Investigate suspicious activities and unauthorized access\n- Monitor team member actions and account usage\n\nKey information returned:\n- Complete user activity details and timestamps\n- User identification (email, IP address, browser)\n- Action types and activity descriptions\n- Security-relevant events and access logs\n- Historical activity data for audit trails\n\nNote: Requires Enterprise plan for access to organization activity logs.',
  operationId: 'getAccountActivity',
  request: {
    query: z.object({
      startDate: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Mandatory if endDate is used. Enter start date in UTC date (YYYY-MM-DD)\nformat to filter the activity in your account. Maximum time period that\ncan be selected is one month. Additionally, you can retrieve activity\nlogs from the past 12 months from the date of your search.',
            in: 'query',
            name: 'startDate',
            required: false,
            schema: { type: 'string' },
          },
        }),
      endDate: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Mandatory if startDate is used. Enter end date in UTC date (YYYY-MM-DD)\nformat to filter the activity in your account. Maximum time period that\ncan be selected is one month.',
            in: 'query',
            name: 'endDate',
            required: false,
            schema: { type: 'string' },
          },
        }),
      email: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: "Enter the user's email address to filter their activity in the account.",
            in: 'query',
            name: 'email',
            required: false,
            schema: { type: 'string' },
          },
        }),
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(1n).max(100n))
        .default(10n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Number of documents per page',
            in: 'query',
            name: 'limit',
            required: false,
            schema: { default: 10, format: 'int64', maximum: 100, minimum: 1, type: 'integer' },
          },
        }),
      offset: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Index of the first document in the page.',
            in: 'query',
            name: 'offset',
            required: false,
            schema: { default: 0, format: 'int64', type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'list of user activity logs',
      content: {
        'application/json': {
          schema: z
            .object({
              logs: z
                .array(
                  z
                    .object({
                      action: z
                        .string()
                        .openapi({
                          description: 'Type of activity in the account.',
                          example: 'login-success',
                        }),
                      date: z
                        .string()
                        .openapi({
                          description: 'Time of the activity.',
                          example: '2023-03-27T16:30:00Z',
                        }),
                      user_agent: z
                        .string()
                        .openapi({
                          description: 'Browser details of the user who performed the activity.',
                          example: 'Mozilla/5.0 (iPad; U; CPU OS 3_2_1 like Mac OS X; en-us)',
                        }),
                      user_email: z
                        .string()
                        .openapi({
                          description:
                            'Email address of the user who performed activity in the\naccount.',
                          example: 'test@mycompany.com',
                        }),
                      user_ip: z
                        .string()
                        .openapi({
                          description:
                            'IP address of the user who performed activity in the\naccount.',
                          example: '192.158.1.38',
                        }),
                    })
                    .openapi({
                      required: ['action', 'date', 'user_email', 'user_ip', 'user_agent'],
                    }),
                )
                .exactOptional()
                .openapi({ description: 'Get user activity logs' }),
            })
            .openapi({ required: [] }),
          examples: {
            response: {
              value: {
                logs: [
                  {
                    action: 'login-success',
                    date: '2023-03-16T16:49:23+05:30',
                    user_agent: 'Mozilla/5.0 (iPad; U; CPU OS 3_2_1 like Mac OS X; en-us)',
                    user_email: 'test@mycompany.com',
                    user_ip: '192.158.1.34',
                  },
                  {
                    action: 'update-profile',
                    count: 2,
                    date: '2023-03-15T16:49:23+05:30',
                    user_agent: 'Mozilla/5.0 (iPad; U; CPU OS 3_2_1 like Mac OS X; en-us)',
                    user_email: 'test@myexample.com',
                    user_ip: '192.158.1.38',
                  },
                ],
              },
            },
          },
        },
      },
    },
    400: ErrorModelResponse,
  },
})

