export const getProcessesRoute = createRoute({
  method: 'get',
  path: '/processes',
  tags: ['Process'],
  summary: 'Get background processes',
  description:
    'Retrieves a list of background processes from your Brevo account with filtering and pagination.\n\n**Use this to:**\n- Monitor background process activity and status\n- Track long-running operations and tasks\n- Find process IDs for detailed status checking\n- Review process history and performance\n- Identify failed or stuck processes for troubleshooting\n\n**Key information returned:**\n- Process details (ID, name, status)\n- Export download URLs for completed export processes\n- Import details with CSV report URLs for completed import processes\n- Total count of processes for pagination\n\n**Important considerations:**\n- Background processes handle long-running operations like imports and exports\n- Process status indicates current state (queued, processing, completed)\n- Export processes provide download URLs when completed\n- Import processes provide CSV report URLs with details about problematic records\n- Use pagination for accounts with many historical processes\n- Sort options available for creation order (ascending or descending)\n- Default limit is 10 results per page, maximum is 50\n',
  operationId: 'getProcesses',
  request: {
    query: z.object({
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(1n).max(50n))
        .default(10n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Number limitation for the result returned',
            in: 'query',
            name: 'limit',
            schema: { default: 10, format: 'int64', maximum: 50, minimum: 1, type: 'integer' },
            required: false,
          },
        }),
      offset: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Beginning point in the list to retrieve from.',
            in: 'query',
            name: 'offset',
            schema: { default: 0, format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      sort: z
        .enum(['asc', 'desc'])
        .default('desc')
        .exactOptional()
        .openapi({
          param: {
            description:
              'Sort the results in the ascending/descending order of record creation.\nDefault order is **descending** if `sort` is not passed',
            in: 'query',
            name: 'sort',
            required: false,
            schema: { default: 'desc', enum: ['asc', 'desc'], type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Background processes retrieved successfully',
      content: {
        'application/json': {
          schema: z
            .object({
              count: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  description: 'Total number of processes available on your account',
                  example: 198,
                }),
              processes: z
                .array(
                  z
                    .object({
                      id: z
                        .preprocess(
                          (val) =>
                            typeof val === 'number' && Number.isSafeInteger(val)
                              ? BigInt(val)
                              : typeof val === 'string' && /^-?\d+$/.test(val)
                                ? BigInt(val)
                                : val,
                          z.int64(),
                        )
                        .openapi({
                          type: 'integer',
                          format: 'int64',
                          description: 'Unique identifier of the process',
                          example: 217,
                        }),
                      name: z
                        .enum([
                          'IMPORTUSER',
                          'SEARCH_EXPORT_USERS',
                          'TRANS-CALC',
                          'TRANS-GLOBAL-CALC',
                          'CAMPAIGN_PROCESSING',
                          'LIST_EXPORT',
                          'CONTACT_EXPORT',
                        ])
                        .openapi({
                          description: 'Name/type of the process',
                          example: 'IMPORTUSER',
                        }),
                      status: z
                        .enum(['queued', 'processing', 'completed', 'failed', 'cancelled'])
                        .openapi({
                          description: 'Current status of the process',
                          example: 'completed',
                        }),
                      info: z
                        .object({
                          import: z
                            .object({
                              invalid_emails: z
                                .string()
                                .nullable()
                                .exactOptional()
                                .openapi({
                                  description:
                                    'URL to CSV file containing invalid email addresses, or null if none',
                                }),
                              duplicate_contact_id: z
                                .string()
                                .nullable()
                                .exactOptional()
                                .openapi({
                                  description:
                                    'URL to CSV file containing duplicate contact IDs, or null if none',
                                }),
                              duplicate_ext_id: z
                                .string()
                                .nullable()
                                .exactOptional()
                                .openapi({
                                  description:
                                    'URL to CSV file containing duplicate external IDs, or null if none',
                                }),
                              duplicate_email_id: z
                                .string()
                                .nullable()
                                .exactOptional()
                                .openapi({
                                  description:
                                    'URL to CSV file containing duplicate email IDs, or null if none',
                                }),
                              duplicate_phone_id: z
                                .string()
                                .nullable()
                                .exactOptional()
                                .openapi({
                                  description:
                                    'URL to CSV file containing duplicate phone numbers, or null if none',
                                }),
                              duplicate_whatsapp_id: z
                                .string()
                                .nullable()
                                .exactOptional()
                                .openapi({
                                  description:
                                    'URL to CSV file containing duplicate WhatsApp numbers, or null if none',
                                }),
                              duplicate_landline_number_id: z
                                .string()
                                .nullable()
                                .exactOptional()
                                .openapi({
                                  description:
                                    'URL to CSV file containing duplicate landline numbers, or null if none',
                                }),
                            })
                            .exactOptional()
                            .openapi({
                              description: 'Import process details with URLs to CSV reports',
                              required: [],
                            }),
                        })
                        .exactOptional()
                        .openapi({
                          description:
                            'Additional process information, only returned for completed IMPORTUSER processes. Contains URLs to CSV files with details about problematic records.',
                          required: [],
                        }),
                      export_url: z
                        .url()
                        .exactOptional()
                        .openapi({
                          description:
                            'Download URL for completed export processes (returned for SEARCH_EXPORT_USERS, SEARCH_EXPORT_USERS_API, CAMPAIGN_USER_DETAILS, and EXPORT_WEBHOOK process types)',
                          example:
                            'https://s3.eu-west-1.amazonaws.com/api-export.example.com/upload/contacts_export.csv',
                        }),
                    })
                    .openapi({ required: ['id', 'name', 'status'] }),
                )
                .openapi({ description: 'List of background processes on your account' }),
            })
            .openapi({ required: ['count', 'processes'] }),
          examples: {
            processes_response: {
              summary: 'List of background processes with various statuses',
              value: {
                count: 198,
                processes: [
                  {
                    id: 217,
                    name: 'IMPORTUSER',
                    status: 'completed',
                    info: {
                      import: {
                        invalid_emails: null,
                        duplicate_contact_id: null,
                        duplicate_ext_id: null,
                        duplicate_email_id: null,
                        duplicate_phone_id: null,
                        duplicate_whatsapp_id: null,
                        duplicate_landline_number_id: null,
                      },
                    },
                  },
                  {
                    id: 213,
                    name: 'SEARCH_EXPORT_USERS',
                    status: 'completed',
                    export_url:
                      'https://s3.eu-west-1.amazonaws.com/api-export.example.com/upload/contacts_export.csv',
                  },
                  { id: 212, name: 'IMPORTUSER', status: 'queued' },
                ],
              },
            },
          },
        },
      },
    },
    400: ErrorModelResponse,
  },
})

