export const getWebhooksWebhookIdRoute = createRoute({
  method: 'get',
  path: '/webhooks/{webhookId}',
  tags: ['Webhooks'],
  summary: 'Get a webhook details',
  description:
    'Retrieves detailed information about a specific webhook configuration.\n\nUse this to:\n- Get complete webhook configuration and settings\n- Check webhook event subscriptions and triggers\n- Review authentication and security settings\n- Verify webhook URL and custom headers\n- Access webhook creation and modification history\n\nKey information returned:\n- Complete webhook details and configuration\n- Event types and channel subscriptions\n- Authentication credentials and methods\n- Custom headers and request settings\n- Webhook status and activity information',
  operationId: 'getWebhook',
  request: {
    params: z.object({
      webhookId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description: 'Id of the webhook',
            in: 'path',
            name: 'webhookId',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Webhook informations',
      content: {
        'application/json': {
          schema: GetWebhookSchema,
          examples: {
            response: {
              value: {
                auth: { token: 'test-auth-token1234', type: 'bearer' },
                batched: true,
                createdAt: '2016-06-07T09:10:10Z',
                description: 'Webhook triggered on campaign openings and addition of lists',
                events: ['listAddition', 'opened'],
                headers: [{ key: 'cf-secret', value: 'test-header-value' }],
                id: 7287,
                modifiedAt: '2016-06-08T11:30:00Z',
                type: 'marketing',
                url: 'http://example.domain.com/1brxxxxxx5p1',
              },
            },
          },
        },
      },
    },
    400: ErrorModelResponse,
    404: ErrorModelResponse,
  },
})

