export const postContactsImportRoute = createRoute({
  method: 'post',
  path: '/contacts/import',
  tags: ['Contacts'],
  summary: 'Import contacts',
  description:
    "It returns the background process ID which on completion calls the notify URL that you have set in the input. **Note**: - Any contact attribute that doesn't exist in your account will be ignored at import end.\n",
  operationId: 'importContacts',
  request: {
    body: {
      description:
        'Values to import contacts in Brevo. To know more about the expected format, please have a look at ``https://help.brevo.com/hc/en-us/articles/209499265-Build-contacts-lists-for-your-email-marketing-campaigns``',
      content: {
        'application/json': {
          schema: z
            .object({
              disableNotification: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({ description: 'To disable email notification', example: false }),
              emailBlacklist: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description: 'To blacklist all the contacts for email',
                  example: false,
                }),
              emptyContactsAttributes: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'To facilitate the choice to erase any attribute of the existing contacts with empty value. emptyContactsAttributes = true means the empty fields in your import will erase any attribute that currently contain data in Brevo, & emptyContactsAttributes = false means the empty fields will not affect your existing data ( **only available if `updateExistingContacts` set to true **)\n',
                  example: true,
                }),
              fileBody: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    '**Mandatory if fileUrl and jsonBody is not defined.** CSV content to be imported. Use semicolon to separate multiple attributes. **Maximum allowed file body size is 10MB** . However we recommend a safe limit of around 8 MB to avoid the issues caused due to increase of file body size while parsing. Please use fileUrl instead to import bigger files.\n',
                  example:
                    'NAME;SURNAME;EMAIL\nSmith;John;john.smith@example.com\nRoger;Ellie;ellie36@example.com',
                }),
              fileUrl: z
                .url()
                .exactOptional()
                .openapi({
                  description:
                    '**Mandatory if fileBody and jsonBody is not defined.** URL of the file to be imported (**no local file**). Possible file formats: #### .txt, .csv, .json\n',
                  example: 'https://importfile.domain.com',
                }),
              jsonBody: z
                .array(
                  z
                    .object({
                      attributes: z
                        .looseObject({})
                        .exactOptional()
                        .openapi({ description: 'List of attributes to be imported' }),
                      email: z.string().exactOptional(),
                    })
                    .openapi({
                      example: {
                        attributes: {
                          BIRTHDAY: '11/02/1989',
                          COUNTRY: 'DE',
                          FNAME: 'Dicky',
                          LANDLINE_NUMBER: '33689965433',
                          LNAME: 'Noemi',
                          PREFERED_COLOR: 'BLACK',
                          SMS: '33689965433',
                          WHATSAPP: '33689965433',
                        },
                        email: 'ndicky0@ocn.ne.jp',
                      },
                      required: [],
                    }),
                )
                .exactOptional()
                .openapi({
                  description:
                    '**Mandatory if fileUrl and fileBody is not defined.** JSON content to be imported. **Maximum allowed json body size is 10MB** . However we recommend a safe limit of around 8 MB to avoid the issues caused due to increase of json body size while parsing. Please use fileUrl instead to import bigger files.\n',
                }),
              listIds: z
                .array(
                  z
                    .preprocess(
                      (val) =>
                        typeof val === 'number' && Number.isSafeInteger(val)
                          ? BigInt(val)
                          : typeof val === 'string' && /^-?\d+$/.test(val)
                            ? BigInt(val)
                            : val,
                      z.int64(),
                    )
                    .openapi({
                      type: 'integer',
                      format: 'int64',
                      description: 'List Id in which the contacts shall be imported',
                      example: 76,
                    }),
                )
                .exactOptional()
                .openapi({
                  description:
                    '**Mandatory if newList is not defined.** Ids of the lists in which the contacts shall be imported. For example, **[2, 4, 7]**.\n',
                }),
              consentGroupIds: z
                .array(
                  z
                    .preprocess(
                      (val) =>
                        typeof val === 'number' && Number.isSafeInteger(val)
                          ? BigInt(val)
                          : typeof val === 'string' && /^-?\d+$/.test(val)
                            ? BigInt(val)
                            : val,
                      z.int64(),
                    )
                    .openapi({
                      type: 'integer',
                      format: 'int64',
                      description: 'Consent group Id',
                      example: 1,
                    }),
                )
                .exactOptional()
                .openapi({
                  description:
                    '**Optional.** Ids of the consent groups to which all imported contacts will be added. Requires consent groups to be enabled for the organisation. For example, **[1, 3]**.\n',
                }),
              newList: z
                .object({
                  folderId: z
                    .preprocess(
                      (val) =>
                        typeof val === 'number' && Number.isSafeInteger(val)
                          ? BigInt(val)
                          : typeof val === 'string' && /^-?\d+$/.test(val)
                            ? BigInt(val)
                            : val,
                      z.int64(),
                    )
                    .exactOptional()
                    .openapi({
                      type: 'integer',
                      format: 'int64',
                      description:
                        'Id of the folder where this new list shall be created. **Mandatory if listName is not empty**\n',
                      example: 2,
                    }),
                  listName: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        'List with listName will be created first and users will be imported in it. **Mandatory if listIds is empty**.\n',
                      example: 'ContactImport - 2017-05',
                    }),
                })
                .exactOptional()
                .openapi({
                  description:
                    'To create a new list and import the contacts into it, pass the listName and an optional folderId.',
                  required: [],
                }),
              notifyUrl: z
                .url()
                .exactOptional()
                .openapi({
                  description:
                    'URL that will be called once the import process is finished. For reference, https://help.brevo.com/hc/en-us/articles/360007666479',
                  example: 'http://requestb.in/173lyyx1',
                }),
              smsBlacklist: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({ description: 'To blacklist all the contacts for sms', example: false }),
              updateExistingContacts: z
                .boolean()
                .default(true)
                .exactOptional()
                .openapi({
                  description: 'To facilitate the choice to update the existing contacts',
                  example: true,
                }),
            })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: { 202: CreatedProcessIdResponse, 400: ErrorModelResponse },
})

