export const getContactsConsentGroupsRoute = createRoute({
  method: 'get',
  path: '/contacts/consent-groups',
  tags: ['ConsentGroups'],
  summary: 'List all consent groups',
  description:
    'Returns a paginated list of consent groups for the account.\n\n<Note>This endpoint is only available when the Consent Groups feature is enabled for your account. Returns `403` if the feature is not activated.</Note>',
  operationId: 'getConsentGroups',
  request: {
    query: z.object({
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(0n).max(50n))
        .default(10n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Maximum number of results to return (default 10, max 50)',
            in: 'query',
            name: 'limit',
            schema: { type: 'integer', format: 'int64', default: 10, maximum: 50, minimum: 0 },
            required: false,
          },
        }),
      offset: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(0n))
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Number of results to skip (default 0)',
            in: 'query',
            name: 'offset',
            schema: { type: 'integer', format: 'int64', default: 0, minimum: 0 },
            required: false,
          },
        }),
      id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by consent group ID',
            in: 'query',
            name: 'id',
            schema: { type: 'integer', format: 'int64' },
            required: false,
          },
        }),
      name: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by name (case-insensitive partial match)',
            in: 'query',
            name: 'name',
            schema: { type: 'string' },
            required: false,
          },
        }),
      signupMode: z
        .enum(['manual', 'automatic'])
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by signup mode',
            in: 'query',
            name: 'signupMode',
            schema: { type: 'string', enum: ['manual', 'automatic'] },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Paginated list of consent groups',
      content: {
        'application/json': {
          schema: ConsentGroupsListResponseSchema,
          examples: {
            response: {
              value: {
                consentGroups: [
                  {
                    id: 1,
                    name: 'Newsletter EU',
                    description: 'Consent group for EU newsletter subscribers',
                    signupMode: 'manual',
                    contactsCount: 1234,
                    isDefault: false,
                    createdAt: '2024-01-15T10:00:00Z',
                    updatedAt: '2024-06-01T08:30:00Z',
                  },
                ],
                total: 1,
                limit: 10,
                offset: 0,
              },
            },
          },
        },
      },
    },
    400: {
      description:
        'Bad request. Possible error codes: `INVALID_ID` (invalid id filter value), `INVALID_SIGNUP_MODE` (invalid signupMode value).',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    403: {
      description:
        'Consent Groups feature not enabled for this account. Error code: `CONSENT_GROUP_NOT_ENABLED`.',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    429: {
      description: 'Too Many Requests',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
  },
})

