export const putContactsIdentifierRoute = createRoute({
  method: 'put',
  path: '/contacts/{identifier}',
  tags: ['Contacts'],
  summary: 'Update a contact',
  description:
    '<Note>Follow this format when passing a "SMS" phone number as an attribute.\nAccepted Number Formats 91xxxxxxxxxx +91xxxxxxxxxx 0091xxxxxxxxxx</Note>\nThere are 2 ways to update a contact <br><br> Option 1- https://api.brevo.com/v3/contacts/{identifier} <br><br> Option 2- https://api.brevo.com/v3/contacts/{identifier}?identifierType={} <br> <br> Option 1 only works if identifierType is email_id (for EMAIL) or contact_id (for ID of the contact),where you can directly pass the value of EMAIL and ID of the contact.   <br><br> Option 2 works for all identifierType, use email_id for EMAIL attribute, contact_id for ID of the contact, ext_id for EXT_ID attribute, phone_id for SMS attribute, whatsapp_id for WHATSAPP attribute, landline_number_id for LANDLINE_NUMBER attribute',
  operationId: 'updateContact',
  request: {
    params: z.object({
      identifier: ((schema) =>
        z.union([
          z.preprocess(
            (val) =>
              typeof val === 'string' &&
              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                ? Number(val)
                : val,
            schema,
          ),
          schema,
        ]))(z.xor([z.string(), z.int()])).openapi({
        param: {
          description:
            'Email (urlencoded) OR ID of the contact OR EXT_ID attribute (urlencoded) OR its SMS attribute value OR its WHATSAPP attribute value OR its LANDLINE_NUMBER attribute value',
          in: 'path',
          name: 'identifier',
          required: true,
          schema: { oneOf: [{ type: 'string' }, { type: 'integer' }] },
        },
      }),
    }),
    query: z.object({
      identifierType: z
        .enum(['email_id', 'contact_id', 'ext_id', 'phone_id', 'whatsapp_id', 'landline_number_id'])
        .exactOptional()
        .openapi({
          param: {
            description:
              'email_id for Email, contact_id for ID of the contact, ext_id for EXT_ID attribute, phone_id for SMS attribute, whatsapp_id for WHATSAPP attribute, landline_number_id for LANDLINE_NUMBER attribute',
            in: 'query',
            name: 'identifierType',
            schema: {
              enum: [
                'email_id',
                'contact_id',
                'ext_id',
                'phone_id',
                'whatsapp_id',
                'landline_number_id',
              ],
              type: 'string',
            },
            required: false,
          },
        }),
    }),
    body: {
      description: 'Values to update a contact',
      content: {
        'application/json': {
          schema: z
            .object({
              attributes: z
                .record(
                  z.string(),
                  z.xor([z.number(), z.string(), z.boolean(), z.array(z.string())]),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Pass the set of attributes to be updated. **These attributes must be present in your account**. To update existing email address of a contact with the new one please pass EMAIL in attributes. For example, **{ "EMAIL":"newemail@domain.com", "FNAME":"Ellie", "LNAME":"Roger", "COUNTRIES":["India","China"]}**. The attribute\'s parameter should be passed in capital letter while updating a contact. Values that don\'t match the attribute type (e.g. text or string in a date attribute) will be ignored .Keep in mind transactional attributes can be updated the same way as normal attributes. Mobile Number in **SMS** field should be passed with proper country code. For example: **{"SMS":"+91xxxxxxxxxx"} or {"SMS":"0091xxxxxxxxxx"}**\n',
                  example: {
                    COUNTRIES: ['India', 'China'],
                    EMAIL: 'newemail@domain.com',
                    FNAME: 'Ellie',
                    LNAME: 'Roger',
                  },
                }),
              emailBlacklisted: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Set/unset this field to blacklist/allow the contact for emails (emailBlacklisted = true)',
                  example: false,
                }),
              ext_id: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Pass your own Id to update ext_id of a contact.',
                  example: 'updateExternalId',
                }),
              listIds: z
                .array(
                  z
                    .preprocess(
                      (val) =>
                        typeof val === 'number' && Number.isSafeInteger(val)
                          ? BigInt(val)
                          : typeof val === 'string' && /^-?\d+$/.test(val)
                            ? BigInt(val)
                            : val,
                      z.int64(),
                    )
                    .openapi({
                      type: 'integer',
                      format: 'int64',
                      description: 'Id of the list to add the contact to',
                      example: 65,
                    }),
                )
                .exactOptional()
                .openapi({ description: 'Ids of the lists to add the contact to' }),
              smsBlacklisted: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Set/unset this field to blacklist/allow the contact for SMS (smsBlacklisted = true)',
                  example: true,
                }),
              smtpBlacklistSender: z
                .array(z.email())
                .exactOptional()
                .openapi({
                  description:
                    'transactional email forbidden sender for contact. Use only for email Contact',
                }),
              unlinkListIds: z
                .array(
                  z
                    .preprocess(
                      (val) =>
                        typeof val === 'number' && Number.isSafeInteger(val)
                          ? BigInt(val)
                          : typeof val === 'string' && /^-?\d+$/.test(val)
                            ? BigInt(val)
                            : val,
                      z.int64(),
                    )
                    .openapi({
                      type: 'integer',
                      format: 'int64',
                      description: 'Id of the list to remove the contact from',
                      example: 36,
                    }),
                )
                .exactOptional()
                .openapi({ description: 'Ids of the lists to remove the contact from' }),
              forceMerge: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'When true, if the contact being updated shares an identifier (email, SMS, ext_id, whatsapp, landline) with an existing contact, the two contacts are force-merged. The contact with the most recent `last_modified` timestamp is retained; the other is deleted. When false (default), a 4xx error is returned on identifier conflict.',
                  example: true,
                }),
            })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    204: { description: 'Contact updated', content: {} },
    400: {
      description: 'bad request',
      content: { 'application/json': { schema: ContactErrorModelSchema } },
    },
    404: {
      description: 'Contact not found',
      content: { 'application/json': { schema: ContactErrorModelSchema } },
    },
    425: {
      description: 'Too Early',
      content: { 'application/json': { schema: ContactErrorModelSchema } },
    },
  },
})

