export const postCouponsRoute = createRoute({
  method: 'post',
  path: '/coupons',
  tags: ['Coupons'],
  summary: 'Create coupons for a coupon collection',
  description:
    'Add coupons to an existing coupon collection. The `coupons` array must contain between 1 and 10,000 unique coupon code strings, all associated with the specified `collectionId`. Coupon creation is processed asynchronously and a `204` status is returned immediately upon acceptance. Returns a `404` error if the specified coupon collection does not exist.',
  operationId: 'createCoupons',
  request: {
    body: {
      description: 'Values to create coupons',
      content: {
        'application/json': {
          schema: z
            .object({
              collectionId: z
                .uuidv4()
                .openapi({
                  description:
                    'The id of the coupon collection for which the coupons will be created',
                  example: '23befbae-1505-47a8-bd27-e30ef739f32c',
                }),
              coupons: z
                .array(z.string().openapi({ description: 'Name of the coupon', example: 'Uf12AF' }))
                .min(1)
                .max(10000)
                .superRefine((items, ctx) => {
                  const seen = new Map()
                  for (const [i, val] of items.entries()) {
                    const key = JSON.stringify(val)
                    if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                    else seen.set(key, i)
                  }
                }),
            })
            .openapi({ required: ['collectionId', 'coupons'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    204: { description: 'Coupons creation in progress', content: {} },
    400: ErrorModelResponse,
    401: ErrorModelResponse,
    404: {
      description: 'Coupon collection not found',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
  },
})

