export const getOrdersRoute = createRoute({
  method: 'get',
  path: '/orders',
  tags: ['Ecommerce'],
  summary: 'Get order details',
  description: 'Get all the orders',
  operationId: 'getOrders',
  request: {
    query: z.object({
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().max(100n))
        .default(50n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Number of documents per page',
            in: 'query',
            name: 'limit',
            schema: { default: 50, format: 'int64', maximum: 100, type: 'integer' },
            required: false,
          },
        }),
      offset: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Index of the first document in the page',
            in: 'query',
            name: 'offset',
            schema: { default: 0, format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      sort: z
        .enum(['asc', 'desc'])
        .default('desc')
        .exactOptional()
        .openapi({
          param: {
            description:
              'Sort the results in the ascending/descending order of record creation. Default order is **descending** if `sort` is not passed',
            in: 'query',
            name: 'sort',
            required: false,
            schema: { default: 'desc', enum: ['asc', 'desc'], type: 'string' },
          },
        }),
      secondarySortByModifiedAt: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description:
              'When `true`, orders with the same `createdAt` are then ordered by their `updatedAt`, in the same direction as `sort`. Use it to get a stable order when paging through the results with `limit` and `offset`. Default is `false`.',
            in: 'query',
            name: 'secondarySortByModifiedAt',
            required: false,
            schema: { default: false, type: 'boolean' },
          },
        }),
      modifiedSince: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter (urlencoded) the orders modified after a given UTC date-time (YYYY-MM-DDTHH:mm:ss.SSSZ). **Prefer to pass your timezone in date-time format for accurate result.**\n',
            in: 'query',
            name: 'modifiedSince',
            schema: { type: 'string' },
            required: false,
          },
        }),
      createdSince: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter (urlencoded) the orders created after a given UTC date-time (YYYY-MM-DDTHH:mm:ss.SSSZ). **Prefer to pass your timezone in date-time format for accurate result.**\n',
            in: 'query',
            name: 'createdSince',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: { description: 'orders fetched successfully', content: {} },
    400: ErrorModelResponse,
  },
})

