export const postProductsRoute = createRoute({
  method: 'post',
  path: '/products',
  tags: ['Ecommerce'],
  summary: 'Create/Update a product',
  description:
    'Create a new ecommerce product or update an existing one, identified by the mandatory `id` field. When `updateEnabled` is `false` (the default), the endpoint inserts a new product and returns `201`; if the product ID already exists, a `400` error is returned. When `updateEnabled` is `true`, the endpoint performs an upsert, returning `201` for a new product or `204` for an update. The `name` field is mandatory for creation but optional for updates. Product images are downloaded, validated (max 5 MB, formats: jpeg, jpg, png, bmp, gif, webp), and re-hosted on S3. The `metaInfo` object supports up to 20 keys with a cumulative size limit of approximately 1000 KB.',
  operationId: 'createUpdateProduct',
  request: {
    body: {
      description: 'Values to create/update a product',
      content: {
        'application/json': {
          schema: z
            .object({
              brand: z
                .string()
                .max(128)
                .exactOptional()
                .openapi({ description: 'Brand of the product', example: 'Adidas' }),
              categories: z
                .array(z.string())
                .exactOptional()
                .openapi({ description: 'Category ID-s of the product' }),
              deletedAt: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "UTC date-time (YYYY-MM-DDTHH:mm:ss.SSSZ) of the product deleted from the shop's database",
                  example: '2017-05-12T12:30:00Z',
                }),
              description: z
                .string()
                .max(3000)
                .exactOptional()
                .openapi({
                  description: 'Description of the product',
                  example: 'Shoes for sports',
                }),
              id: z
                .string()
                .openapi({
                  description: 'Product ID for which you requested the details',
                  example: 'P11',
                }),
              imageUrl: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Absolute URL to the cover image of the product',
                  example: 'http://mydomain.com/product-absoulte-url/img.jpeg',
                }),
              isDeleted: z
                .boolean()
                .exactOptional()
                .openapi({
                  description: "product deleted from the shop's database",
                  example: true,
                }),
              metaInfo: z
                .record(z.string(), z.xor([z.string(), z.int()]))
                .exactOptional()
                .openapi({
                  description:
                    'Meta data of product such as description, vendor, producer, stock level. The total characters of cumulative metaInfo shall not exceed **20000 characters**.',
                  example: { brand: 'addidas', description: 'Shoes for sports' },
                }),
              name: z
                .string()
                .openapi({
                  description:
                    '**Mandatory in case of creation**. Name of the product, as displayed in the shop',
                  example: 'Iphone 11',
                }),
              parentId: z
                .string()
                .exactOptional()
                .openapi({ description: 'Parent product id of the product' }),
              price: z.float32().exactOptional().openapi({ description: 'Price of the product' }),
              alternativePrice: z
                .float32()
                .exactOptional()
                .openapi({ description: 'Alternative price of the product' }),
              sku: z
                .string()
                .exactOptional()
                .openapi({ description: 'Product identifier from the shop' }),
              stock: z
                .number()
                .exactOptional()
                .openapi({
                  description: "Current stock value of the product from the shop's database",
                  example: 100,
                }),
              updateEnabled: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'Facilitate to update the existing product in the same request (updateEnabled = true)',
                  example: false,
                }),
              url: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'URL to the product',
                  example: 'http://mydomain.com/product/electronics/product1',
                }),
            })
            .openapi({ required: ['id', 'name'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Product created',
      content: {
        'application/json': {
          schema: z
            .object({
              id: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'ID of the product when a new product is created',
                  example: 'P11',
                }),
            })
            .openapi({ required: [] }),
          examples: { response: { value: { id: 21 } } },
        },
      },
    },
    204: { description: 'Product updated' },
    400: ErrorModelResponse,
  },
})

