export const getEventsRoute = createRoute({
  method: 'get',
  path: '/events',
  tags: ['Event'],
  summary: 'Get events',
  description: 'Retrieve a list of events filtered by various criteria.',
  operationId: 'getEvents',
  request: {
    query: z.object({
      contact_id: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            z
              .preprocess((val) => {
                if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
                  return val
                if (/^-?\d+$/.test(val)) return BigInt(val)
                const num = Number(val)
                return Number.isSafeInteger(num) ? BigInt(num) : val
              }, z.int64())
              .openapi({ type: 'integer', format: 'int64' }),
          ),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by contact ID (repeatable)',
            explode: true,
            in: 'query',
            name: 'contact_id',
            required: false,
            schema: { items: { format: 'int64', type: 'integer' }, type: 'array' },
            style: 'form',
          },
        }),
      event_name: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by event name (repeatable)',
            explode: true,
            in: 'query',
            name: 'event_name',
            required: false,
            schema: { items: { type: 'string' }, type: 'array' },
            style: 'form',
          },
        }),
      object_type: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by object type (repeatable)',
            explode: true,
            in: 'query',
            name: 'object_type',
            required: false,
            schema: { items: { type: 'string' }, type: 'array' },
            style: 'form',
          },
        }),
      startDate: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Mandatory if endDate is used. Start of date range (YYYY-MM-DD or RFC3339). Defaults to 6 months ago when omitted alongside endDate. Must be ≤ endDate.',
            in: 'query',
            name: 'startDate',
            required: false,
            schema: { type: 'string' },
          },
        }),
      endDate: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Mandatory if startDate is used. End of date range (YYYY-MM-DD or RFC3339). Must be ≥ startDate.',
            in: 'query',
            name: 'endDate',
            required: false,
            schema: { type: 'string' },
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(10000),
        )
        .default(100)
        .exactOptional()
        .openapi({
          param: {
            description: 'Max events to return. Default 100, min 1, max 10000.',
            in: 'query',
            name: 'limit',
            required: false,
            schema: { default: 100, maximum: 10000, minimum: 1, type: 'integer' },
          },
        }),
      offset: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(0),
        )
        .default(0)
        .exactOptional()
        .openapi({
          param: {
            description: 'Events to skip for pagination. Default 0, min 0.',
            in: 'query',
            name: 'offset',
            required: false,
            schema: { default: 0, minimum: 0, type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'List of events and total count for pagination',
      content: {
        'application/json': {
          schema: GetEventsListSchema,
          example: {
            count: 2,
            events: [
              {
                contact_id: 211,
                event_date: '2024-02-06T20:59:23.383Z',
                event_name: 'order_created',
                event_filter_id: 'abc123',
                object_type: 'subscription',
                event_properties: {
                  duration: 142,
                  video_title: 'Brevo — The most approachable CRM suite',
                },
                contact_properties: { AGE: 32, GENDER: 'FEMALE' },
              },
            ],
          },
        },
      },
    },
    400: ErrorModelResponse,
    401: ErrorModelResponse,
    500: ErrorModelResponse,
  },
})

export const postEventsRoute = createRoute({
  method: 'post',
  path: '/events',
  tags: ['Event'],
  summary: 'Create an event',
  description: "Create an event to track a contact's interaction.",
  operationId: 'createEvent',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              contact_properties: z
                .record(z.string(), z.union([z.string(), z.number(), z.boolean()]))
                .exactOptional()
                .openapi({
                  description:
                    'Properties defining the state of the contact associated to this event. Useful to update contact attributes defined in your contacts database while passing the event. For example: **"FIRSTNAME": "Jane" , "AGE": 37**',
                  example: { AGE: 32, GENDER: 'FEMALE' },
                }),
              event_date: z.iso
                .datetime({ offset: true })
                .exactOptional()
                .openapi({
                  description:
                    'ISO 8601 timestamp of when the event occurred (e.g. "2024-01-24T17:39:57+01:00"). If no value is passed, the timestamp of the event creation is used.',
                  example: '2024-02-06T20:59:23.383Z',
                }),
              event_name: z
                .string()
                .max(255)
                .openapi({
                  description:
                    'The name of the event that occurred. This is how you will find your event in Brevo. Limited to 255 characters; only alphanumeric characters, hyphens (-), and underscores (_) are allowed.',
                  example: 'video_played',
                }),
              event_properties: z
                .record(
                  z.string(),
                  z.union([z.string(), z.number(), z.boolean(), z.object({}), z.array(z.any())]),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Properties of the event. Top level properties and nested properties can be used to better segment contacts and personalise workflow conditions. The following field types are supported: string, number, boolean (true/false), date (Timestamp e.g. "2024-01-24T17:39:57+01:00"). Keys are limited to 255 characters, alphanumerical characters and - _ only. Size is limited to 50KB.',
                  example: {
                    autoplayed: false,
                    duration: 142,
                    upload_date: '2023-11-24T12:09:10+01:00',
                    video_description: 'Create your free account today!',
                    video_title: 'Brevo — The most approachable CRM suite',
                  },
                }),
              identifiers: z
                .object({
                  contact_id: z
                    .preprocess(
                      (val) =>
                        typeof val === 'number' && Number.isSafeInteger(val)
                          ? BigInt(val)
                          : typeof val === 'string' && /^-?\d+$/.test(val)
                            ? BigInt(val)
                            : val,
                      z.int64(),
                    )
                    .exactOptional()
                    .openapi({
                      type: 'integer',
                      format: 'int64',
                      description:
                        'Internal unique contact ID. When present, this takes priority over all other identifiers for event attribution and contact resolution.',
                      example: 211,
                    }),
                  email_id: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description: 'Email Id associated with the event',
                      example: 'jane.doe@example.com',
                    }),
                  ext_id: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description: 'ext_id associated with the event',
                      example: 'abc123',
                    }),
                  landline_number_id: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description: 'landline_number associated with the event',
                      example: '+91xxxxxxxxxx',
                    }),
                  phone_id: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description: 'SMS associated with the event',
                      example: '+91xxxxxxxxxx',
                    }),
                  whatsapp_id: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description: 'whatsapp associated with the event',
                      example: '+91xxxxxxxxxx',
                    }),
                })
                .refine((val) => Object.keys(val).length >= 1)
                .openapi({
                  description:
                    'Identifies the contact associated with the event. At least one identifier is required.',
                  required: [],
                }),
              object: z
                .object({
                  identifiers: z
                    .object({
                      ext_id: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'External object ID', example: 'sub-59374-linwn' }),
                      id: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'Internal object ID', example: '178140' }),
                    })
                    .exactOptional()
                    .openapi({ description: 'Identifiers for the object.', required: [] }),
                  type: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description: 'Type of object (e.g., subscription, vehicle, etc.)',
                      example: 'subscription',
                    }),
                })
                .exactOptional()
                .openapi({
                  description:
                    'Identifiers of the object record associated with this event. Ignored if the object type or identifier for this record does not exist on the account.',
                  required: [],
                }),
            })
            .openapi({ required: ['event_name', 'identifiers'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    204: { description: 'Event posted', content: {} },
    400: ErrorModelResponse,
    401: ErrorModelResponse,
  },
})

