export const getLoyaltyBalanceProgramsPidActiveBalanceRoute = createRoute({
  method: 'get',
  path: '/loyalty/balance/programs/{pid}/active-balance',
  tags: ['Balance'],
  summary: 'Get Active Balances API',
  description: 'Returns Active Balances',
  request: {
    params: z.object({
      pid: z
        .uuid()
        .openapi({
          param: {
            description: 'Loyalty Program Id',
            in: 'path',
            name: 'pid',
            required: true,
            schema: { format: 'uuid', type: 'string' },
          },
        }),
    }),
    query: z.object({
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(500),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Limit',
            in: 'query',
            name: 'limit',
            schema: { maximum: 500, minimum: 1, type: 'integer' },
            required: false,
          },
        }),
      offset: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(0),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Offset',
            in: 'query',
            name: 'offset',
            schema: { minimum: 0, type: 'integer' },
            required: false,
          },
        }),
      sortField: z
        .literal('createdAt')
        .exactOptional()
        .openapi({
          param: {
            description: 'Sort Field',
            in: 'query',
            name: 'sortField',
            schema: { enum: ['createdAt'], type: 'string' },
            required: false,
          },
        }),
      sort: z
        .enum(['asc', 'desc'])
        .exactOptional()
        .openapi({
          param: {
            description: 'Sort Order',
            in: 'query',
            name: 'sort',
            schema: { enum: ['asc', 'desc'], type: 'string' },
            required: false,
          },
        }),
      contactId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(1n))
        .openapi({
          param: {
            description: 'Contact ID',
            in: 'query',
            name: 'contactId',
            required: true,
            schema: { format: 'int64', minimum: 1, type: 'integer' },
          },
        }),
      balanceDefinitionId: z
        .uuid()
        .openapi({
          param: {
            description: 'Balance Definition ID',
            in: 'query',
            name: 'balanceDefinitionId',
            required: true,
            schema: { format: 'uuid', type: 'string' },
          },
        }),
      includeInternal: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description: 'Include balances tied to internal definitions.',
            in: 'query',
            name: 'includeInternal',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful retrieval of active balances',
      content: {
        'application/json': {
          schema: z
            .object({
              count: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .exactOptional()
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  description: 'Total number of active balances.',
                }),
              loyaltyProgramId: z
                .uuid()
                .exactOptional()
                .openapi({ description: 'Unique identifier of the loyalty program.' }),
              contactId: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .exactOptional()
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  description: 'Unique identifier of the contact.',
                }),
              balanceDefinitionId: z
                .uuid()
                .exactOptional()
                .openapi({ description: 'Unique identifier of the balance definition.' }),
              activeBalances: z
                .array(
                  z
                    .object({
                      id: z
                        .uuid()
                        .exactOptional()
                        .openapi({ description: 'Unique identifier of the balance entry.' }),
                      amount: z
                        .float32()
                        .exactOptional()
                        .openapi({ description: 'Current balance amount.' }),
                      createdAt: z.iso
                        .datetime({ offset: true })
                        .exactOptional()
                        .openapi({ description: 'Timestamp when the balance was created.' }),
                      expiresAt: z.iso
                        .datetime({ offset: true })
                        .exactOptional()
                        .openapi({
                          description: 'Timestamp when the balance expires (if applicable).',
                        }),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional()
                .openapi({ description: 'List of active balances.' }),
            })
            .openapi({
              description: 'Active balance response for a specific contact and balance definition.',
              required: [],
            }),
        },
      },
    },
    401: {
      description: 'Request Authentication Failed',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    403: {
      description: 'Cannot Authenticate Request',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    404: {
      description: 'subscription not found',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    422: {
      description: 'Validation errors',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    500: {
      description: 'Internal error occurred',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
  },
})

