export const postLoyaltyBalanceProgramsPidBalanceDefinitionsRoute = createRoute({
  method: 'post',
  path: '/loyalty/balance/programs/{pid}/balance-definitions',
  tags: ['Balance'],
  summary: 'Create balance definition',
  description: 'Creates balance definition and returns information',
  request: {
    params: z.object({
      pid: z
        .uuid()
        .openapi({
          param: {
            description: 'Loyalty Program Id',
            in: 'path',
            name: 'pid',
            required: true,
            schema: { format: 'uuid', type: 'string' },
          },
        }),
    }),
    body: {
      description: 'Create Balance Definition Payload',
      content: {
        'application/json': {
          schema: z
            .object({
              balanceAvailabilityDurationModifier: z
                .enum(['noModification', 'startOfPeriod', 'endOfPeriod'])
                .exactOptional()
                .openapi({
                  description: 'Defines when the balance expires within the selected duration.',
                }),
              balanceAvailabilityDurationUnit: z
                .enum(['day', 'week', 'month', 'year'])
                .exactOptional()
                .openapi({ description: 'Unit of time for balance validity.' }),
              balanceAvailabilityDurationValue: z
                .int()
                .exactOptional()
                .openapi({ description: 'Number of time units before the balance expires.' }),
              balanceExpirationDate: z.iso
                .date()
                .exactOptional()
                .openapi({
                  description:
                    'Fixed expiration date (`dd/mm` format) as an alternative to duration-based expiry.',
                }),
              balanceOptionAmountOvertakingStrategy: z
                .enum(['strict', 'partial'])
                .exactOptional()
                .openapi({
                  description:
                    'Defines whether partial credit is allowed when reaching max balance.',
                }),
              balanceOptionCreditRounding: z
                .enum(['lower', 'upper', 'natural'])
                .exactOptional()
                .openapi({ description: 'Defines rounding strategy for credit transactions.' }),
              balanceOptionDebitRounding: z
                .enum(['lower', 'upper', 'natural'])
                .exactOptional()
                .openapi({ description: 'Defines rounding strategy for debit transactions.' }),
              description: z
                .string()
                .max(256)
                .exactOptional()
                .openapi({ description: 'Short description of the balance definition.' }),
              imageRef: z
                .string()
                .exactOptional()
                .openapi({ description: 'URL of an optional image reference.' }),
              maxAmount: z
                .number()
                .exactOptional()
                .openapi({ description: 'Maximum allowable balance amount.' }),
              maxCreditAmountLimit: z
                .number()
                .exactOptional()
                .openapi({ description: 'Maximum credit allowed per operation.' }),
              maxDebitAmountLimit: z
                .number()
                .exactOptional()
                .openapi({ description: 'Maximum debit allowed per operation.' }),
              meta: z
                .looseObject({
                  isInternal: z
                    .boolean()
                    .exactOptional()
                    .openapi({
                      description: 'Indicates whether the balance definition is internal.',
                    }),
                })
                .exactOptional()
                .openapi({
                  description: 'Additional metadata for the balance definition.',
                  example: { isInternal: true },
                  required: [],
                }),
              minAmount: z
                .number()
                .exactOptional()
                .openapi({ description: 'Minimum allowable balance amount.' }),
              name: z.string().max(128).openapi({ description: 'Name of the balance definition.' }),
              unit: z
                .enum([
                  'POINTS',
                  'EUR',
                  'USD',
                  'MXN',
                  'GBP',
                  'INR',
                  'CAD',
                  'SGD',
                  'RON',
                  'JPY',
                  'MYR',
                  'CLP',
                  'PEN',
                  'MAD',
                  'AUD',
                  'CHF',
                  'BRL',
                ])
                .openapi({ description: 'Unit of balance measurement.' }),
            })
            .openapi({
              description:
                'Payload for creating a new balance definition, specifying expiration rules, rounding strategies, and constraints.',
              required: ['name', 'unit'],
            }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Successful creation of balance definition',
      content: { 'application/json': { schema: BalanceDefinitionSchema } },
    },
    401: {
      description: 'Request Authentication Failed',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    403: {
      description: 'Cannot Authenticate Request',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    404: {
      description: 'No content',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    422: {
      description: 'Validation errors',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    500: {
      description: 'Internal error occurred',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
  },
})

