export const getLoyaltyBalanceProgramsPidContactBalancesRoute = createRoute({
  method: 'get',
  path: '/loyalty/balance/programs/{pid}/contact-balances',
  tags: ['Balance'],
  summary: 'Get balance list',
  description: 'Returns contact balances for a given balance definition across all subscriptions.',
  operationId: 'getContactBalances',
  request: {
    params: z.object({
      pid: z
        .uuid()
        .openapi({
          param: {
            description: 'Loyalty Program Id',
            in: 'path',
            name: 'pid',
            required: true,
            schema: { format: 'uuid', type: 'string' },
          },
        }),
    }),
    query: z.object({
      includeInternal: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description: 'Include balances tied to internal definitions.',
            in: 'query',
            name: 'includeInternal',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(500),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Limit the number of records returned',
            in: 'query',
            name: 'limit',
            schema: { maximum: 500, minimum: 1, type: 'integer' },
            required: false,
          },
        }),
      offset: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(0),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Skip a number of records',
            in: 'query',
            name: 'offset',
            schema: { minimum: 0, type: 'integer' },
            required: false,
          },
        }),
      sort: z
        .enum(['asc', 'desc'])
        .exactOptional()
        .openapi({
          param: {
            description: 'Sort order',
            in: 'query',
            name: 'sort',
            schema: { enum: ['asc', 'desc'], type: 'string' },
            required: false,
          },
        }),
      sortField: z
        .enum(['updatedAt', 'value'])
        .exactOptional()
        .openapi({
          param: {
            description: 'Field to sort by',
            in: 'query',
            name: 'sortField',
            schema: { enum: ['updatedAt', 'value'], type: 'string' },
            required: false,
          },
        }),
      balanceDefinitionId: z
        .uuid()
        .openapi({
          param: {
            description: 'Balance Definition ID (required)',
            in: 'query',
            name: 'balanceDefinitionId',
            required: true,
            schema: { format: 'uuid', type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful retrieval of contact balance',
      content: {
        'application/json': {
          schema: z
            .object({
              balanceDefinitionId: z.string().exactOptional(),
              balances: z
                .array(
                  z
                    .object({
                      contactId: z.int().exactOptional(),
                      loyaltySubscriptionId: z.string().exactOptional(),
                      updatedAt: z.string().exactOptional(),
                      value: z.number().exactOptional(),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional(),
              count: z.int().exactOptional(),
              loyaltyProgramId: z.string().exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
    401: {
      description: 'Request Authentication Failed',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    403: {
      description: 'Cannot Authenticate Request',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    404: {
      description: 'subscription data not found for some contacts',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    422: {
      description: 'Validation errors',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    500: {
      description: 'Internal error occurred',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
  },
})

