export const getLoyaltyBalanceProgramsPidTransactionHistoryRoute = createRoute({
  method: 'get',
  path: '/loyalty/balance/programs/{pid}/transaction-history',
  tags: ['Balance'],
  summary: 'Get Transaction History API',
  description: 'Returns transaction history',
  request: {
    params: z.object({
      pid: z
        .uuid()
        .openapi({
          param: {
            description: 'Loyalty Program Id',
            in: 'path',
            name: 'pid',
            required: true,
            schema: { format: 'uuid', type: 'string' },
          },
        }),
    }),
    query: z.object({
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(500),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Limit the number of records returned',
            in: 'query',
            name: 'limit',
            schema: { maximum: 500, minimum: 1, type: 'integer' },
            required: false,
          },
        }),
      offset: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(0),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Page number to retrieve',
            in: 'query',
            name: 'offset',
            schema: { minimum: 0, type: 'integer' },
            required: false,
          },
        }),
      sortField: z
        .literal('createdAt')
        .default('createdAt')
        .exactOptional()
        .openapi({
          param: {
            description: 'Field to sort by',
            in: 'query',
            name: 'sortField',
            schema: { default: 'createdAt', enum: ['createdAt'], type: 'string' },
            required: false,
          },
        }),
      sort: z
        .enum(['asc', 'desc'])
        .exactOptional()
        .openapi({
          param: {
            description: 'Sort order',
            in: 'query',
            name: 'sort',
            schema: { enum: ['asc', 'desc'], type: 'string' },
            required: false,
          },
        }),
      contactId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(1n))
        .openapi({
          param: {
            description: 'Contact ID',
            in: 'query',
            name: 'contactId',
            required: true,
            schema: { format: 'int64', minimum: 1, type: 'integer' },
          },
        }),
      balanceDefinitionId: z
        .uuid()
        .openapi({
          param: {
            description: 'Balance Definition ID',
            in: 'query',
            name: 'balanceDefinitionId',
            required: true,
            schema: { format: 'uuid', type: 'string' },
          },
        }),
      status: z
        .enum(['draft', 'completed', 'rejected', 'cancelled', 'expired'])
        .exactOptional()
        .openapi({
          param: {
            description: 'Transaction status filter',
            in: 'query',
            name: 'status',
            schema: {
              enum: ['draft', 'completed', 'rejected', 'cancelled', 'expired'],
              type: 'string',
            },
            required: false,
          },
        }),
      transactionType: z
        .enum(['credit', 'debit'])
        .exactOptional()
        .openapi({
          param: {
            description: 'Transaction type filter',
            in: 'query',
            name: 'transactionType',
            schema: { enum: ['credit', 'debit'], type: 'string' },
            required: false,
          },
        }),
      loyaltySubscriptionId: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Loyalty Subscription ID filter',
            in: 'query',
            name: 'loyaltySubscriptionId',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful retrieval of transaction history',
      content: {
        'application/json': {
          schema: z
            .object({
              balanceDefinitionId: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Unique identifier of the associated balance definition.',
                }),
              contactId: z
                .int()
                .exactOptional()
                .openapi({
                  description: 'Unique identifier of the contact related to the transactions.',
                }),
              count: z
                .int()
                .exactOptional()
                .openapi({ description: 'Total number of transactions in the history.' }),
              loyaltyProgramId: z
                .string()
                .exactOptional()
                .openapi({ description: 'Unique identifier of the associated loyalty program.' }),
              transactionHistory: z
                .array(
                  z
                    .object({
                      amount: z
                        .float32()
                        .exactOptional()
                        .openapi({ description: 'The transaction amount.' }),
                      transactionType: z
                        .enum(['credit', 'debit'])
                        .exactOptional()
                        .openapi({ description: 'The type of the transaction.' }),
                      balanceExpirationDate: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            'Expiration date of the balance associated with this transaction.',
                        }),
                      cancelledAt: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            'Timestamp when the transaction was canceled, if applicable.',
                        }),
                      completedAt: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description: 'Timestamp when the transaction was successfully completed.',
                        }),
                      createdAt: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'Timestamp when the transaction was initiated.' }),
                      id: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'Unique identifier of the transaction.' }),
                      meta: z
                        .looseObject({})
                        .exactOptional()
                        .openapi({
                          description: 'Optional metadata associated with the transaction.',
                        }),
                      rejectReason: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description: 'Reason for rejection, if the transaction was declined.',
                        }),
                      rejectedAt: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'Timestamp when the transaction was rejected.' }),
                      status: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            'Current status of the transaction (e.g., pending, completed, rejected).',
                        }),
                    })
                    .openapi({
                      description:
                        'Represents a record of a past transaction, including status and key timestamps.',
                      required: [],
                    }),
                )
                .exactOptional()
                .openapi({ description: 'List of past transactions associated with the balance.' }),
            })
            .openapi({
              description:
                'Response containing transaction history details for a specific balance and contact.',
              required: [],
            }),
        },
      },
    },
    401: {
      description: 'Request Authentication Failed',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    403: {
      description: 'Cannot Authenticate Request',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    404: {
      description: 'subscription not found',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    422: {
      description: 'Validation errors',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    500: {
      description: 'Internal error occurred',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
  },
})

export const postLoyaltyBalanceProgramsPidTransactionsRoute = createRoute({
  method: 'post',
  path: '/loyalty/balance/programs/{pid}/transactions',
  tags: ['Balance'],
  summary: 'Create new transaction',
  description: 'Creates new transaction and returns information',
  operationId: 'beginTransaction',
  request: {
    params: z.object({
      pid: z
        .uuid()
        .openapi({
          param: {
            description: 'Loyalty Program Id',
            in: 'path',
            name: 'pid',
            required: true,
            schema: { format: 'uuid', type: 'string' },
          },
        }),
    }),
    body: {
      description: 'Transaction Payload',
      content: {
        'application/json': {
          schema: z
            .object({
              amount: z
                .number()
                .openapi({
                  description:
                    'Transaction amount. A positive value creates a credit transaction and a negative value creates a debit transaction (unless transactionType is explicitly provided).',
                }),
              transactionType: z
                .enum(['credit', 'debit'])
                .exactOptional()
                .openapi({
                  description:
                    'Explicit transaction type. If not provided, the type is inferred from the sign of the amount (positive = credit, negative = debit).',
                }),
              balanceDefinitionId: z
                .uuid()
                .openapi({
                  description: 'Unique identifier (UUID) of the associated balance definition.',
                }),
              contactId: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64().min(1n),
                )
                .exactOptional()
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  minimum: 1,
                  description:
                    'Unique identifier of the contact involved in the transaction. Required unless `LoyaltySubscriptionId` is provided.',
                }),
              LoyaltySubscriptionId: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Unique identifier for the loyalty subscription. Required unless `contactId` is provided.',
                }),
              meta: z
                .looseObject({})
                .exactOptional()
                .openapi({ description: 'Optional metadata associated with the transaction.' }),
              ttl: z
                .int()
                .min(10)
                .exactOptional()
                .openapi({
                  description:
                    'Time-to-live for the transaction in seconds. Must be at least 10 seconds if provided.',
                }),
              eventTime: z.iso
                .datetime({ offset: true })
                .exactOptional()
                .openapi({
                  description:
                    'Timestamp specifying when the transaction event occurred (ISO 8601 / RFC 3339 format).',
                }),
              autoComplete: z
                .boolean()
                .exactOptional()
                .openapi({
                  description: 'Whether the transaction should be automatically completed.',
                }),
              balanceExpiryInMinutes: z
                .int()
                .min(1)
                .exactOptional()
                .openapi({
                  description:
                    'Expiry time for the balance in minutes. Must be greater than 0 if provided. Only applicable when autoComplete is true.',
                }),
            })
            .openapi({
              description:
                'Payload for creating a transaction, specifying balance details and optional expiration.',
              required: ['amount', 'balanceDefinitionId'],
            }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Transaction created successfully',
      content: { 'application/json': { schema: TransactionSchema } },
    },
    401: {
      description: 'Request Authentication Failed',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    403: {
      description: 'Cannot Authenticate Request',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    404: {
      description: 'Transaction not found',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    422: {
      description: 'Validation errors',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    500: {
      description: 'Internal error occurred',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
  },
})

