export const deleteLoyaltyConfigProgramsPidContactCidRoute = createRoute({
  method: 'delete',
  path: '/loyalty/config/programs/{pid}/contact/{cid}',
  tags: ['Program'],
  summary: 'Delete subscription',
  description: 'Delete subscription for a contact',
  operationId: 'deleteContactSubscription',
  request: {
    params: z.object({
      pid: z
        .uuid()
        .openapi({
          param: {
            description: 'Loyalty Program ID. A unique identifier for the loyalty program.',
            in: 'path',
            name: 'pid',
            required: true,
            schema: { format: 'uuid', type: 'string' },
          },
        }),
      cid: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            description: 'Contact ID.',
            in: 'path',
            name: 'cid',
            required: true,
            schema: { type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    204: { description: 'Successfully deleted subscription.' },
    400: {
      description: 'Invalid loyalty program or contact ID.',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    401: {
      description: 'Request Authentication Failed.',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    403: {
      description: 'Cannot Authenticate Request.',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    404: {
      description: 'Subscription not found.',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    422: {
      description: 'Cannot delete subscription.',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    500: {
      description: 'Internal error occurred.',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
  },
})

