export const getLoyaltyOfferProgramsPidOffersRoute = createRoute({
  method: 'get',
  path: '/loyalty/offer/programs/{pid}/offers',
  tags: ['Reward'],
  summary: 'Get Reward Page API',
  description: 'Returns a reward page',
  request: {
    params: z.object({
      pid: z
        .uuid()
        .openapi({
          param: {
            description: 'Loyalty Program ID',
            in: 'path',
            name: 'pid',
            required: true,
            schema: { format: 'uuid', type: 'string' },
          },
        }),
    }),
    query: z.object({
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(100),
        )
        .default(25)
        .exactOptional()
        .openapi({
          param: {
            description: 'Page size',
            in: 'query',
            name: 'limit',
            schema: { default: 25, maximum: 100, minimum: 1, type: 'integer' },
            required: false,
          },
        }),
      offset: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(0)
        .exactOptional()
        .openapi({
          param: {
            description: 'Pagination offset',
            in: 'query',
            name: 'offset',
            schema: { default: 0, type: 'integer' },
            required: false,
          },
        }),
      state: z
        .string()
        .default('all')
        .exactOptional()
        .openapi({
          param: {
            description: 'State of the reward',
            in: 'query',
            name: 'state',
            schema: { default: 'all', type: 'string' },
            required: false,
          },
        }),
      version: z
        .enum(['active', 'draft'])
        .default('draft')
        .exactOptional()
        .openapi({
          param: {
            description: 'Version',
            in: 'query',
            name: 'version',
            schema: { default: 'draft', enum: ['active', 'draft'], type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Reward list successfully retrieved',
      content: {
        'application/json': {
          schema: z
            .object({
              items: z
                .array(
                  z
                    .object({
                      createdAt: z.iso
                        .datetime({ offset: true })
                        .exactOptional()
                        .openapi({ description: 'Timestamp for when this reward was created' }),
                      endDate: z.iso
                        .datetime({ offset: true })
                        .exactOptional()
                        .openapi({
                          description: 'Timestamp for when this reward attribution ended',
                        }),
                      id: z
                        .uuid()
                        .exactOptional()
                        .openapi({ description: 'Unique identifier for the reward' }),
                      loyaltyProgramId: z
                        .uuid()
                        .exactOptional()
                        .openapi({
                          description: 'Loyalty Program to which current reward is associated',
                        }),
                      name: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'Name of the reward' }),
                      publicImage: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'Public image of the reward' }),
                      startDate: z.iso
                        .datetime({ offset: true })
                        .exactOptional()
                        .openapi({
                          description: 'Timestamp for when this reward attribution started',
                        }),
                      state: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'State of the reward' }),
                      updatedAt: z.iso
                        .datetime({ offset: true })
                        .exactOptional()
                        .openapi({
                          description: 'Timestamp for when this reward attribution was updated',
                        }),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional()
                .openapi({ description: 'Items for the current reward' }),
              totalCount: z
                .int()
                .exactOptional()
                .openapi({ description: 'Count of the associated parameter in current reward' }),
            })
            .openapi({ required: [] }),
        },
      },
    },
    401: {
      description: 'Request Authentication Failed',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    403: {
      description: 'Cannot Authenticate Request',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    404: {
      description: 'Not Found',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    422: {
      description: 'Validation errors',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    424: {
      description: 'Failed Dependency',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    500: {
      description: 'Internal error occurred',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
  },
})

