export const getSmsCampaignsRoute = createRoute({
  method: 'get',
  path: '/smsCampaigns',
  tags: ['SMS Campaigns'],
  summary: 'Returns the information for all your created SMS campaigns',
  description:
    'Retrieve a paginated list of all your SMS campaigns with their statistics and recipient information. Results can be filtered by status and date range, with a default limit of 500 and maximum of 1000 per page. The sort order defaults to descending by creation date; date filters are only available when status is not passed or is set to sent.',
  operationId: 'getSmsCampaigns',
  request: {
    query: z.object({
      status: z
        .enum(['suspended', 'archive', 'sent', 'queued', 'draft', 'inProcess'])
        .exactOptional()
        .openapi({
          param: {
            description: 'Status of campaign.',
            in: 'query',
            name: 'status',
            schema: {
              enum: ['suspended', 'archive', 'sent', 'queued', 'draft', 'inProcess'],
              type: 'string',
            },
            required: false,
          },
        }),
      startDate: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              '**Mandatory if endDate is used.** Starting (urlencoded) UTC date-time (YYYY-MM-DDTHH:mm:ss.SSSZ) to filter the sent SMS campaigns. **Prefer to pass your timezone in date-time format for accurate result.** Only available if `status` is not passed or is set to `sent`. `startDate` must not be in the future.\n',
            in: 'query',
            name: 'startDate',
            schema: { type: 'string' },
            required: false,
          },
        }),
      endDate: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              '**Mandatory if startDate is used.** Ending (urlencoded) UTC date-time (YYYY-MM-DDTHH:mm:ss.SSSZ) to filter the sent SMS campaigns. **Prefer to pass your timezone in date-time format for accurate result.** Only available if `status` is not passed or is set to `sent`. `endDate` must not be in the future.\n',
            in: 'query',
            name: 'endDate',
            schema: { type: 'string' },
            required: false,
          },
        }),
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(1n).max(1000n))
        .default(500n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Number of documents per page',
            in: 'query',
            name: 'limit',
            schema: { default: 500, format: 'int64', maximum: 1000, minimum: 1, type: 'integer' },
            required: false,
          },
        }),
      offset: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Beginning point in the list to retrieve from.',
            in: 'query',
            name: 'offset',
            schema: { default: 0, format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      sort: z
        .enum(['asc', 'desc'])
        .default('desc')
        .exactOptional()
        .openapi({
          param: {
            description:
              'Sort the results in the ascending/descending order of record creation. Default order is **descending** if `sort` is not passed',
            in: 'query',
            name: 'sort',
            required: false,
            schema: { default: 'desc', enum: ['asc', 'desc'], type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'SMS campaigns information',
      content: {
        'application/json': {
          schema: z
            .object({
              campaigns: z
                .array(
                  GetSmsCampaignOverviewSchema.and(
                    z
                      .object({
                        recipients: GetCampaignRecipientsSchema,
                        statistics: GetSmsCampaignStatsSchema,
                      })
                      .openapi({ required: ['recipients', 'statistics'] }),
                  ),
                )
                .exactOptional(),
              count: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .exactOptional()
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  description: 'Number of SMS campaigns retrieved',
                  example: 12,
                }),
            })
            .openapi({ required: [] }),
          examples: {
            response: {
              value: {
                campaigns: [
                  {
                    content: 'Visit our Store and get some discount !',
                    createdAt: '2017-06-01T12:30:00Z',
                    id: 2,
                    modifiedAt: '2017-05-01T12:30:00Z',
                    name: 'PROMO CODE',
                    organisationPrefix: 'MyCompany',
                    recipients: { exclusionLists: [13], lists: [21] },
                    scheduledAt: '2017-06-01T12:30:00Z',
                    sender: 'MyCompany',
                    sentDate: '2017-06-01T12:30:00Z',
                    statistics: {
                      answered: 2,
                      delivered: 2987,
                      hardBounces: 1,
                      processing: 0,
                      sent: 3000,
                      softBounces: 3,
                      unsubscriptions: 3,
                    },
                    status: 'sent',
                    unsubscribeInstruction: 'send Stop if you want to unsubscribe.',
                  },
                  {
                    content: 'Summer Sale is starting tomorrow. Get extra 10% with this code:SUM17',
                    createdAt: '2017-06-01T12:30:00Z',
                    id: 10,
                    modifiedAt: '2017-05-01T12:30:00Z',
                    name: 'SUMMER SALE',
                    organisationPrefix: '',
                    recipients: { exclusionLists: [13], lists: [21] },
                    scheduledAt: '2017-08-04T12:30:00Z',
                    sender: 'MyCompany',
                    statistics: {
                      answered: 2,
                      delivered: 2987,
                      hardBounces: 1,
                      processing: 0,
                      sent: 3000,
                      softBounces: 3,
                      unsubscriptions: 3,
                    },
                    status: 'draft',
                    unsubscribeInstruction: '',
                  },
                ],
                count: 12,
              },
            },
          },
        },
      },
    },
    400: ErrorModelResponse,
  },
})

export const postSmsCampaignsRoute = createRoute({
  method: 'post',
  path: '/smsCampaigns',
  tags: ['SMS Campaigns'],
  summary: 'Creates an SMS campaign',
  description:
    'Create a new SMS campaign with the required name, sender, and content fields. The sender name is limited to 11 alphanumeric characters or 15 numeric characters, and the content should stay within 160 characters per SMS segment. If a scheduledAt date is provided, listIds in recipients become mandatory; accounts under validation are limited to 4 total campaigns and campaigns with more than 10 recipients will be saved as draft.',
  operationId: 'createSmsCampaign',
  request: {
    body: {
      description: 'Values to create an SMS Campaign',
      content: {
        'application/json': {
          schema: z
            .object({
              content: z
                .string()
                .openapi({
                  description:
                    'Content of the message. The **maximum characters used per SMS is 160**, if used more than that, it will be counted as more than one SMS.\n',
                  example: 'Get a discount by visiting our NY store and saying : Happy Spring!',
                }),
              name: z
                .string()
                .openapi({ description: 'Name of the campaign', example: 'Spring Promo Code' }),
              organisationPrefix: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'A recognizable prefix will ensure your audience knows who you are. Recommended by U.S. carriers. This will be added as your Brand Name before the message content. **Prefer verifying maximum length of 160 characters including this prefix in message content to avoid multiple sending of same sms.**',
                  example: 'MyCompany',
                }),
              recipients: z
                .object({
                  exclusionListIds: z
                    .array(
                      z
                        .preprocess(
                          (val) =>
                            typeof val === 'number' && Number.isSafeInteger(val)
                              ? BigInt(val)
                              : typeof val === 'string' && /^-?\d+$/.test(val)
                                ? BigInt(val)
                                : val,
                          z.int64(),
                        )
                        .openapi({
                          type: 'integer',
                          format: 'int64',
                          description: 'List Id to exclude from the campaign',
                          example: 15,
                        }),
                    )
                    .exactOptional()
                    .openapi({ description: 'List ids which have to be excluded from a campaign' }),
                  listIds: z
                    .array(
                      z
                        .preprocess(
                          (val) =>
                            typeof val === 'number' && Number.isSafeInteger(val)
                              ? BigInt(val)
                              : typeof val === 'string' && /^-?\d+$/.test(val)
                                ? BigInt(val)
                                : val,
                          z.int64(),
                        )
                        .openapi({
                          type: 'integer',
                          format: 'int64',
                          description: 'List Id to send the campaign to',
                          example: 54,
                        }),
                    )
                    .openapi({
                      description:
                        'Lists Ids to send the campaign to. **REQUIRED if scheduledAt is not empty**\n',
                    }),
                })
                .exactOptional()
                .openapi({ required: ['listIds'] }),
              scheduledAt: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'UTC date-time on which the campaign has to run (YYYY-MM-DDTHH:mm:ss.SSSZ). **Prefer to pass your timezone in date-time format for accurate result.**\n',
                  example: '2017-05-05T12:30:00+02:00',
                }),
              sender: z
                .string()
                .max(15)
                .openapi({
                  description:
                    'Name of the sender. **The number of characters is limited to 11 for alphanumeric characters and 15 for numeric characters**\n',
                  example: 'MyShop',
                }),
              unicodeEnabled: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'Format of the message. It indicates whether the content should be treated as unicode or not.\n',
                  example: true,
                }),
              unsubscribeInstruction: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Instructions to unsubscribe from future communications. Recommended by U.S. carriers. Must include **STOP** keyword. This will be added as instructions after the end of message content. **Prefer verifying maximum length of 160 characters including this instructions in message content to avoid multiple sending of same sms.**',
                  example: 'send Stop if you want to unsubscribe.',
                }),
            })
            .openapi({ required: ['content', 'name', 'sender'] }),
        },
      },
      required: true,
    },
  },
  responses: { 201: CreateModelResponse, 400: ErrorModelResponse },
})

