export const putWhatsappCampaignsCampaignIdRoute = createRoute({
  method: 'put',
  path: '/whatsappCampaigns/{campaignId}',
  tags: ['WhatsApp Campaigns'],
  summary: 'Update a WhatsApp campaign',
  description:
    '<Note>You can use this API for WhatsApp only if you have setup your WhatsApp account on Brevo platform. To setup your WhatsApp account, follow the steps in the guide below.\n[Activating Whatsapp](https://developers.brevo.com/docs/whatsapp-campaigns-1) in your account</Note>\n<Note>This API requires the List and Segment ids as recipients in Body params.You can use the below Contact endpoints to get the required information.\n[Get all the Lists](https://developers.brevo.com/reference/getlists-1)\n[Get all the Segments](https://developers.brevo.com/reference/getsegments)</Note>',
  operationId: 'updateWhatsAppCampaign',
  request: {
    params: z.object({
      campaignId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description: 'id of the campaign',
            in: 'path',
            name: 'campaignId',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
    body: {
      description: 'Values to update a WhatsApp Campaign',
      content: {
        'application/json': {
          schema: z
            .object({
              campaignName: z
                .string()
                .exactOptional()
                .openapi({ description: 'Name of the campaign', example: 'Test WhatsApp' }),
              campaignStatus: z
                .enum(['scheduled', 'suspended'])
                .default('scheduled')
                .exactOptional()
                .openapi({ description: 'Status of the campaign', example: 'scheduled' }),
              recipients: z
                .object({
                  excludedListIds: z
                    .array(
                      z
                        .preprocess(
                          (val) =>
                            typeof val === 'number' && Number.isSafeInteger(val)
                              ? BigInt(val)
                              : typeof val === 'string' && /^-?\d+$/.test(val)
                                ? BigInt(val)
                                : val,
                          z.int64(),
                        )
                        .openapi({ type: 'integer', format: 'int64', example: 8 }),
                    )
                    .exactOptional()
                    .openapi({ description: 'List ids to exclude from the campaign' }),
                  listIds: z
                    .array(
                      z
                        .preprocess(
                          (val) =>
                            typeof val === 'number' && Number.isSafeInteger(val)
                              ? BigInt(val)
                              : typeof val === 'string' && /^-?\d+$/.test(val)
                                ? BigInt(val)
                                : val,
                          z.int64(),
                        )
                        .openapi({ type: 'integer', format: 'int64', example: 32 }),
                    )
                    .exactOptional()
                    .openapi({
                      description:
                        '**Mandatory if scheduledAt is not empty**. List Ids to send the campaign to\n',
                    }),
                  segments: z
                    .array(
                      z
                        .preprocess(
                          (val) =>
                            typeof val === 'number' && Number.isSafeInteger(val)
                              ? BigInt(val)
                              : typeof val === 'string' && /^-?\d+$/.test(val)
                                ? BigInt(val)
                                : val,
                          z.int64(),
                        )
                        .openapi({ type: 'integer', format: 'int64', example: 23 }),
                    )
                    .exactOptional()
                    .openapi({
                      description:
                        '**Mandatory if listIds are not used**. Segment ids to send the campaign to.\n',
                    }),
                })
                .exactOptional()
                .openapi({
                  description: 'Segment ids and List ids to include/exclude from campaign',
                  required: [],
                }),
              rescheduleFor: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Reschedule the sending UTC date-time (YYYY-MM-DDTHH:mm:ss.SSSZ) of campaign. **Prefer to pass your timezone in date-time format for accurate result.For example: **2017-06-01T12:30:00+02:00** Use this field to update the scheduledAt of any existing draft or scheduled WhatsApp campaign.\n',
                  example: '2017-06-01T12:30:00+02:00',
                }),
            })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    204: { description: 'WhatsApp campaign has been deleted', content: {} },
    400: ErrorModelResponse,
  },
})

