export const getCrmDealsRoute = createRoute({
  method: 'get',
  path: '/crm/deals',
  tags: ['Deals'],
  summary: 'Get all deals',
  description:
    'Retrieve a paginated list of deals with optional filtering, sorting, and search capabilities. Results can be filtered by attributes such as deal name or owner, linked companies, linked contacts, or modification/creation timestamps. Default sort order is descending by creation date.',
  request: {
    query: z.object({
      'filters[attributes.deal_name]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter by attributes. If you have a filter for the owner on your end, please send it as filters[attributes.deal_owner] and utilize the account email for the filtering.',
            in: 'query',
            name: 'filters[attributes.deal_name]',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'filters[attributes.deal_owner]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter by the deal owner. Pass the account email address of the deal owner.',
            in: 'query',
            name: 'filters[attributes.deal_owner]',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'filters[attributes.deal_stage]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter by the deal stage. Pass the stage id, retrievable from GET /crm/pipeline/details/{pipelineID}.',
            in: 'query',
            name: 'filters[attributes.deal_stage]',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'filters[attributes.pipeline]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter by the pipeline. Pass the pipeline id, retrievable from GET /crm/pipeline/details/{pipelineID}.',
            in: 'query',
            name: 'filters[attributes.pipeline]',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'filters[linkedCompaniesIds]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by linked companies ids',
            in: 'query',
            name: 'filters[linkedCompaniesIds]',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'filters[linkedContactsIds]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by linked contacts ids',
            in: 'query',
            name: 'filters[linkedContactsIds]',
            schema: { type: 'string' },
            required: false,
          },
        }),
      modifiedSince: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter (urlencoded) the deals modified after a given UTC date-time (YYYY-MM-DDTHH:mm:ss.SSSZ). Prefer to pass your timezone in date-time format for accurate result.',
            in: 'query',
            name: 'modifiedSince',
            schema: { type: 'string' },
            required: false,
          },
        }),
      createdSince: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter (urlencoded) the deals created after a given UTC date-time (YYYY-MM-DDTHH:mm:ss.SSSZ). Prefer to pass your timezone in date-time format for accurate result.',
            in: 'query',
            name: 'createdSince',
            schema: { type: 'string' },
            required: false,
          },
        }),
      offset: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description: 'Index of the first document of the page',
            in: 'query',
            name: 'offset',
            schema: { format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(50n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Number of documents per page',
            in: 'query',
            name: 'limit',
            schema: { default: 50, format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      sort: z
        .enum(['asc', 'desc'])
        .exactOptional()
        .openapi({
          param: {
            description:
              'Sort the results in the ascending/descending order. Default order is **descending** by creation if `sort` is not passed',
            in: 'query',
            name: 'sort',
            schema: { enum: ['asc', 'desc'], type: 'string' },
            required: false,
          },
        }),
      sortBy: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The field used to sort field names.',
            in: 'query',
            name: 'sortBy',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returns deals list with filters',
      content: {
        'application/json': {
          schema: z
            .object({
              items: z.array(DealSchema).exactOptional().openapi({ description: 'List of deals' }),
            })
            .openapi({ description: 'List of Deals', required: [] }),
        },
      },
    },
    400: ErrorModelResponse,
  },
})

