export const postCrmTasksRoute = createRoute({
  method: 'post',
  path: '/crm/tasks',
  tags: ['Tasks'],
  summary: 'Create a task',
  description:
    'Create a new CRM task with the specified name, type, due date, and optional associations to contacts, companies, or deals. A task requires a name, task type ID, and due date at minimum. You can also set a duration, notes, a reminder, and assign the task to a specific user.',
  request: {
    body: {
      description: 'Task name.',
      content: {
        'application/json': {
          schema: z
            .object({
              assignToId: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'To assign a task to a user you can use either the account email or ID.',
                  example: '5faab4b7f195bb3c4c31e62a',
                }),
              companiesIds: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description: 'Companies ids for companies a task is linked to',
                  example: [
                    '61a5ce58c5d4795761045990',
                    '61a5ce58c5d4795761045991',
                    '61a5ce58c5d4795761045992',
                  ],
                }),
              contactsIds: z
                .array(z.int())
                .exactOptional()
                .openapi({
                  description: 'Contact ids for contacts linked to this task',
                  example: [1, 2, 3],
                }),
              date: z.iso
                .datetime({ offset: true })
                .openapi({
                  description: 'Task due date and time',
                  example: '2021-11-01T17:44:54.668Z',
                }),
              dealsIds: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description: 'Deal ids for deals a task is linked to',
                  example: [
                    '61a5ce58c5d4795761045990',
                    '61a5ce58c5d4795761045991',
                    '61a5ce58c5d4795761045992',
                  ],
                }),
              done: z
                .boolean()
                .exactOptional()
                .openapi({ description: 'Task marked as done', example: false }),
              duration: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64().min(0n),
                )
                .exactOptional()
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  minimum: 0,
                  description: 'Duration of task in milliseconds [1 minute = 60000 ms]',
                  example: 600000,
                }),
              name: z
                .string()
                .openapi({ description: 'Name of task', example: 'Task: Connect with client' }),
              notes: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Notes added to a task',
                  example: 'In communication with client for resolution of queries.',
                }),
              reminder: TaskReminderSchema.exactOptional(),
              taskTypeId: z
                .string()
                .openapi({
                  description: 'Id for type of task e.g Call / Email / Meeting etc.',
                  example: '61a5cd07ca1347c82306ad09',
                }),
            })
            .openapi({ required: ['name', 'taskTypeId', 'date'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Created new task',
      content: {
        'application/json': {
          schema: z
            .object({
              id: z
                .string()
                .openapi({ description: 'Unique task id', example: '61a5cd07ca1347c82306ad06' }),
            })
            .openapi({ description: 'Task Details', required: ['id'] }),
        },
      },
    },
    400: { description: 'Returned when invalid data posted' },
  },
})

