export const getSmtpBlockedContactsRoute = createRoute({
  method: 'get',
  path: '/smtp/blockedContacts',
  tags: ['Transactional emails'],
  summary: 'Get the list of blocked or unsubscribed transactional contacts',
  description:
    'Retrieve a paginated list of transactional contacts that have been blocked or unsubscribed, along with the reason for blocking (e.g. hard bounce, admin blocked, spam complaint, or unsubscription via email/API/Marketing Automation). Both `startDate` and `endDate` must be provided together when filtering by date range, and neither date can be in the future. Results default to 50 per page (max 100) and are sorted in descending order of record creation unless overridden with the `sort` parameter.',
  operationId: 'getTransacBlockedContacts',
  request: {
    query: z.object({
      startDate: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              '**Mandatory if endDate is used.** Starting date (YYYY-MM-DD) from which you want to fetch the blocked or unsubscribed contacts\n',
            in: 'query',
            name: 'startDate',
            schema: { type: 'string' },
            required: false,
          },
        }),
      endDate: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              '**Mandatory if startDate is used.** Ending date (YYYY-MM-DD) till which you want to fetch the blocked or unsubscribed contacts\n',
            in: 'query',
            name: 'endDate',
            schema: { type: 'string' },
            required: false,
          },
        }),
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(0n).max(100n))
        .default(50n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Number of documents returned per page',
            in: 'query',
            name: 'limit',
            schema: { default: 50, format: 'int64', maximum: 100, minimum: 0, type: 'integer' },
            required: false,
          },
        }),
      offset: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Index of the first document on the page',
            in: 'query',
            name: 'offset',
            schema: { default: 0, format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      senders: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'Comma separated list of emails of the senders from which contacts are blocked or unsubscribed',
            explode: false,
            in: 'query',
            name: 'senders',
            schema: { items: { type: 'string' }, type: 'array' },
            style: 'form',
            required: false,
          },
        }),
      sort: z
        .enum(['asc', 'desc'])
        .default('desc')
        .exactOptional()
        .openapi({
          param: {
            description:
              'Sort the results in the ascending/descending order of record creation. Default order is **descending** if `sort` is not passed',
            in: 'query',
            name: 'sort',
            required: false,
            schema: { default: 'desc', enum: ['asc', 'desc'], type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'List of blocked or unsubscribed transactional contacts',
      content: {
        'application/json': {
          schema: z
            .object({
              contacts: z
                .array(
                  z
                    .object({
                      blockedAt: z
                        .string()
                        .openapi({
                          description: 'Date when the contact was blocked or unsubscribed on',
                          example: '2017-05-01T12:30:00Z',
                        }),
                      email: z
                        .email()
                        .openapi({
                          description: 'Email address of the blocked or unsubscribed contact',
                          example: 'john.smith@example.com',
                        }),
                      reason: z
                        .object({
                          code: z
                            .enum([
                              'unsubscribedViaMA',
                              'unsubscribedViaEmail',
                              'adminBlocked',
                              'unsubscribedViaApi',
                              'hardBounce',
                              'contactFlaggedAsSpam',
                            ])
                            .exactOptional()
                            .openapi({
                              description:
                                'Reason code for blocking / unsubscribing (This code is safe for comparison)',
                              example: 'AdminBlocked',
                            }),
                          message: z
                            .string()
                            .exactOptional()
                            .openapi({
                              description:
                                'Reason for blocking / unsubscribing (This string is not safe for comparison)',
                              example: 'Admin blocked',
                            }),
                        })
                        .openapi({
                          description: 'Reason for blocking / unsubscribing',
                          example: 'Admin blocked',
                          required: [],
                        }),
                      senderEmail: z
                        .email()
                        .openapi({
                          description:
                            'Sender email address of the blocked or unsubscribed contact',
                          example: 'john.smith@example.com',
                        }),
                    })
                    .openapi({ required: ['blockedAt', 'email', 'reason', 'senderEmail'] }),
                )
                .exactOptional(),
              count: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .exactOptional()
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  description: 'Count of blocked or unsubscribed contact',
                  example: 1,
                }),
            })
            .openapi({ required: [] }),
          examples: {
            response: {
              value: {
                contacts: [
                  {
                    blockedAt: '2017-05-01T12:30:00Z',
                    email: 'abc@xyz.com',
                    reason: { code: 'adminBlocked', message: 'Admin blocked' },
                    senderEmail: 'ez312@gmal.com',
                  },
                ],
                count: 1,
              },
            },
          },
        },
      },
    },
    400: ErrorModelResponse,
  },
})

