export const getSmtpEmailStatusIdentifierRoute = createRoute({
  method: 'get',
  path: '/smtp/emailStatus/{identifier}',
  tags: ['Transactional emails'],
  summary: 'Fetch scheduled emails by batchId or messageId',
  description:
    'Fetch scheduled batch of emails by batchId or single scheduled email by messageId (Can retrieve data upto 30 days old)',
  operationId: 'getScheduledEmailById',
  request: {
    params: z.object({
      identifier: z
        .string()
        .openapi({
          param: {
            description:
              'The `batchId` of scheduled emails batch (must be a valid UUIDv4) or the `messageId` of scheduled email (enclosed in angle brackets with @ sign, e.g. `<...@domain>`). When using `messageId`, the `limit`, `offset`, `sort`, and `status` query parameters are ignored.',
            examples: {
              batchId: {
                summary: 'batchId of scheduled batch',
                value: '4320f270-a4e3-4a2e-b591-edfe30a5e627',
              },
              messageId: {
                summary: 'messageId of scheduled email',
                value: '<202202231031.53307417725@smtp-relay.mailin.fr>',
              },
            },
            in: 'path',
            name: 'identifier',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      startDate: z.iso
        .date()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Mandatory if `endDate` is used. Starting date (YYYY-MM-DD) from which you want to fetch the list. Cannot be more than 30 days older than the current date.',
            example: '2022-02-02',
            in: 'query',
            name: 'startDate',
            required: false,
            schema: { format: 'date', type: 'string' },
          },
        }),
      endDate: z.iso
        .date()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Mandatory if `startDate` is used. Ending date (YYYY-MM-DD) till which you want to fetch the list. Maximum time period that can be selected is one month.',
            example: '2022-03-02',
            in: 'query',
            name: 'endDate',
            required: false,
            schema: { format: 'date', type: 'string' },
          },
        }),
      sort: z
        .enum(['asc', 'desc'])
        .default('desc')
        .exactOptional()
        .openapi({
          param: {
            description:
              'Sort the results in the ascending/descending order of record creation. Default order is **descending** if `sort` is not passed. Not valid when identifier is `messageId`.',
            in: 'query',
            name: 'sort',
            required: false,
            schema: { default: 'desc', enum: ['asc', 'desc'], type: 'string' },
          },
        }),
      status: z
        .enum(['processed', 'inProgress', 'queued'])
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter the records by `status` of the scheduled email batch or message. Not valid when identifier is `messageId`.',
            in: 'query',
            name: 'status',
            required: false,
            schema: { enum: ['processed', 'inProgress', 'queued'], type: 'string' },
          },
        }),
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(0n).max(500n))
        .default(100n)
        .exactOptional()
        .openapi({
          param: {
            description:
              'Number of documents returned per page. Not valid when identifier is `messageId`.',
            example: 100,
            in: 'query',
            name: 'limit',
            required: false,
            schema: { default: 100, format: 'int64', maximum: 500, minimum: 0, type: 'integer' },
          },
        }),
      offset: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description:
              'Index of the first document on the page.  Not valid when identifier is `messageId`.',
            example: 0,
            in: 'query',
            name: 'offset',
            required: false,
            schema: { default: 0, format: 'int64', type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Scheduled email batches',
      content: {
        'application/json': {
          schema: z.xor([
            z
              .object({
                batches: z
                  .array(
                    z
                      .object({
                        createdAt: z.iso
                          .datetime({ offset: true })
                          .openapi({ description: 'Datetime on which the batch was scheduled' }),
                        scheduledAt: z.iso
                          .datetime({ offset: true })
                          .openapi({ description: 'Datetime for which the batch was scheduled' }),
                        status: z
                          .enum(['inProgress', 'queued', 'processed', 'error'])
                          .openapi({ description: 'Current status of the scheduled batch' }),
                      })
                      .openapi({ required: ['scheduledAt', 'createdAt', 'status'] }),
                  )
                  .exactOptional(),
                count: z.int().exactOptional().openapi({ description: 'Total number of batches' }),
              })
              .openapi({ required: [] }),
            z
              .object({
                createdAt: z.iso
                  .datetime({ offset: true })
                  .openapi({ description: 'Datetime on which the email was scheduled' }),
                scheduledAt: z.iso
                  .datetime({ offset: true })
                  .openapi({ description: 'Datetime for which the email was scheduled' }),
                status: z
                  .enum(['inProgress', 'queued', 'processed', 'error'])
                  .openapi({ description: 'Current status of the scheduled email' }),
              })
              .openapi({ required: ['scheduledAt', 'createdAt', 'status'] }),
          ]),
          examples: {
            batchId: {
              value: {
                batches: [
                  {
                    createdAt: '2022-02-26T11:36:43.576000000Z',
                    scheduledAt: '2022-02-28T11:36:43.576000000Z',
                    status: 'queued',
                  },
                  {
                    createdAt: '2022-02-24T11:36:43.576000000Z',
                    scheduledAt: '2022-02-25T11:36:43.576000000Z',
                    status: 'processed',
                  },
                  {
                    createdAt: '2022-02-25T11:36:43.576000000Z',
                    scheduledAt: '2022-02-26T11:36:43.576000000Z',
                    status: 'inProgress',
                  },
                ],
                count: 3,
              },
            },
            messageId: {
              value: {
                createdAt: '2022-02-26T11:36:43.576000000Z',
                scheduledAt: '2022-02-28T11:36:43.576000000Z',
                status: 'queued',
              },
            },
          },
        },
      },
    },
    400: ErrorModelResponse,
    404: ErrorModelResponse,
  },
})

