export const postTransactionalSMSSendRoute = createRoute({
  method: 'post',
  path: '/transactionalSMS/send',
  tags: ['Transactional SMS'],
  summary: 'Send SMS message asynchronously to a mobile number',
  description:
    '<Note>If the user includes stop code in the Transactional SMS, then it will be switched to Marketing SMS automatically and it will be interpreted as a Marketing SMS. To send Transactional SMS as Transactional, it is important not to use stop code.\nNote: For adding a stop code, client has to add reply STOP to [STOP_CODE] and the [STOP_CODE] will be replaced with the number.</Note>\n<Note title="For end users in France">Transactional SMS can be sent at any time without time restrictions. However, if a message is categorized as Marketing, it must adhere to specific time restrictions. Messages sent outside of these restricted hours will experience delays and will be processed during allowable times. Specifically, Marketing SMS cannot be processed between 10pm and 8am, on Sundays, and on French public holidays.</Note>',
  operationId: 'sendAsyncTransactionalSms',
  request: {
    body: {
      description: 'Values to send a transactional SMS',
      content: { 'application/json': { schema: SendTransacSmsSchema } },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'SMS has been sent successfully to the recipient',
      content: {
        'application/json': {
          schema: z
            .object({
              messageId: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .openapi({ type: 'integer', format: 'int64', example: 1511882900176220 }),
            })
            .openapi({ required: ['messageId'] }),
        },
      },
    },
    400: ErrorModelResponse,
  },
})

export const postTransactionalSMSSmsRoute = createRoute({
  method: 'post',
  path: '/transactionalSMS/sms',
  tags: ['Transactional SMS'],
  summary: 'Send SMS message to a mobile number',
  description:
    'Send a transactional SMS message to a single mobile number. The `sender`, `recipient`, and either `content` or `templateId` fields are required. The sender name is limited to 11 alphanumeric characters or 15 numeric characters, and the recipient must be a valid international phone number (6-15 digits, optional leading +). Tags can be a string or an array of up to 10 strings. The SMS type defaults to `transactional` but can be set to `marketing`; if the content includes a stop code, it is automatically treated as marketing. Returns the message ID, SMS count, credits used, and remaining credits.',
  operationId: 'sendTransacSms',
  request: {
    body: {
      description: 'Values to send a transactional SMS',
      content: { 'application/json': { schema: SendTransacSmsSchema } },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'SMS has been sent successfully to the recipient',
      content: {
        'application/json': {
          schema: z
            .object({
              messageId: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .openapi({ type: 'integer', format: 'int64', example: 1511882900176220 }),
              reference: z.string().openapi({ example: 'ab1cde2fgh3i4jklmno' }),
              remainingCredits: z
                .float32()
                .exactOptional()
                .openapi({ description: 'Remaining SMS credits of the user', example: 82.85 }),
              smsCount: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .exactOptional()
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  description: "Count of SMS's to send multiple text messages",
                  example: 2,
                }),
              usedCredits: z
                .float32()
                .exactOptional()
                .openapi({ description: 'SMS credits used per text message', example: 0.7 }),
            })
            .openapi({ required: ['messageId', 'reference'] }),
        },
      },
    },
    400: ErrorModelResponse,
    402: {
      description: "You don't have enough credit to send your SMS. Please update your plan",
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
    429: {
      description: 'Too many requests. Please retry after some time.',
      content: { 'application/json': { schema: ErrorModelSchema } },
    },
  },
})

